from __future__ import annotations

import hashlib
import hmac
import os
import posixpath
import re
import secrets
from dataclasses import dataclass
from enum import StrEnum

DEFAULT_PBKDF2_ITERATIONS = 1_000_000

# These limits are intentionally generous enough to verify hashes generated by
# older Werkzeug releases, while preventing stored values from making a
# verification request spend arbitrary time or memory in a KDF.
MAX_PASSWORD_HASH_LENGTH = 4096
MAX_SALT_LENGTH = 1024
MAX_HASH_LENGTH = 512
MAX_PBKDF2_ITERATIONS = 5_000_000
MAX_SCRYPT_N = 2**18
MAX_SCRYPT_R = 32
MAX_SCRYPT_P = 16
MAX_SCRYPT_MEMORY = 512 * 1024 * 1024
MAX_SCRYPT_WORK = 8_388_608

_DEFAULT_SCRYPT_N = 2**15
_DEFAULT_SCRYPT_R = 8
_DEFAULT_SCRYPT_P = 1
_DEFAULT_PBKDF2_HASH = "sha256"
_DEFAULT_SCRYPT_METHOD = (
    f"scrypt:{_DEFAULT_SCRYPT_N}:{_DEFAULT_SCRYPT_R}:{_DEFAULT_SCRYPT_P}"
)
_RECOMMENDED_METHOD = "scrypt"
_RECOMMENDED_PARAMETERS = _DEFAULT_SCRYPT_METHOD

_PBKDF2_DIGEST_SIZES = {
    "md5": 16,
    "sha1": 20,
    "sha224": 28,
    "sha256": 32,
    "sha384": 48,
    "sha512": 64,
    "sha512_224": 28,
    "sha512_256": 32,
    "sha3_224": 28,
    "sha3_256": 32,
    "sha3_384": 48,
    "sha3_512": 64,
    "blake2b": 64,
    "blake2s": 32,
}
_WEAK_PBKDF2_DIGESTS = {"md5", "sha1", "sha224"}
_DECIMAL_RE = re.compile(r"[0-9]+\Z")
_HEX_RE = re.compile(r"[0-9a-fA-F]+\Z")
_SAFE_ALGORITHM_RE = re.compile(r"[a-z0-9_]{1,32}\Z")


class PasswordHashStatus(StrEnum):
    """The outcome of :func:`diagnose_password_hash`.

    The status distinguishes bad stored data from a password that simply does
    not match, which lets audit and migration jobs classify records without
    having to parse implementation-specific exception messages.
    """

    OK = "ok"
    PASSWORD_MISMATCH = "password_mismatch"
    MALFORMED = "malformed"
    UNSUPPORTED_ALGORITHM = "unsupported_algorithm"
    LIMIT_EXCEEDED = "limit_exceeded"

    # Readable aliases for callers that prefer more specific names.
    MISMATCH = "password_mismatch"
    WRONG_PASSWORD = "password_mismatch"
    INVALID_FORMAT = "malformed"
    INVALID_PARAMETERS = "malformed"
    BAD_FORMAT = "malformed"
    BUDGET_EXCEEDED = "limit_exceeded"
    OVERSIZED = "limit_exceeded"
    ALGORITHM_NOT_ALLOWED = "unsupported_algorithm"
    UNKNOWN_ALGORITHM = "unsupported_algorithm"


@dataclass(frozen=True)
class PasswordHashDiagnostic:
    """Structured result returned by :func:`diagnose_password_hash`.

    The result never contains the stored salt, stored hash, or supplied
    password. It is safe to include in audit logs.
    """

    status: PasswordHashStatus
    valid: bool
    password_matches: bool
    needs_upgrade: bool
    reason: str
    suggested_method: str | None = None
    suggested_parameters: str | None = None
    upgrade_reason: str | None = None
    algorithm: str | None = None
    format_valid: bool = True
    within_limits: bool = True
    algorithm_supported: bool = True

    @property
    def ok(self) -> bool:
        """Whether the password matched the stored hash."""

        return self.valid

    @property
    def needs_rehash(self) -> bool:
        """Alias for :attr:`needs_upgrade`."""

        return self.needs_upgrade

    @property
    def should_upgrade(self) -> bool:
        """Alias for :attr:`needs_upgrade`."""

        return self.needs_upgrade

    @property
    def upgrade_required(self) -> bool:
        """Alias for :attr:`needs_upgrade`."""

        return self.needs_upgrade

    @property
    def recommended_method(self) -> str | None:
        """Alias for :attr:`suggested_method`."""

        return self.suggested_method

    @property
    def recommended_parameters(self) -> str | None:
        """Alias for :attr:`suggested_parameters`."""

        return self.suggested_parameters

    @property
    def recommendation(self) -> str:
        """The current recommended method and parameters."""

        return _RECOMMENDED_PARAMETERS


class _InvalidPasswordHash(ValueError):
    def __init__(
        self,
        status: PasswordHashStatus,
        reason: str,
        *,
        algorithm: str | None = None,
        format_valid: bool = True,
        within_limits: bool = True,
        algorithm_supported: bool = True,
    ) -> None:
        super().__init__(reason)
        self.status = status
        self.reason = reason
        self.algorithm = algorithm
        self.format_valid = format_valid
        self.within_limits = within_limits
        self.algorithm_supported = algorithm_supported


@dataclass(frozen=True)
class _ParsedPasswordHash:
    algorithm: str
    method: str
    salt: str
    hashval: str
    expected_hash_length: int
    scrypt_n: int | None = None
    scrypt_r: int | None = None
    scrypt_p: int | None = None
    pbkdf2_digest: str | None = None
    pbkdf2_iterations: int | None = None


def _safe_algorithm_name(value: str) -> str | None:
    return value if _SAFE_ALGORITHM_RE.fullmatch(value) else None


def _parse_decimal(value: str, *, algorithm: str, name: str) -> int:
    if not _DECIMAL_RE.fullmatch(value):
        raise _InvalidPasswordHash(
            PasswordHashStatus.MALFORMED,
            f"invalid {name} in stored hash",
            algorithm=algorithm,
            format_valid=False,
        )

    try:
        return int(value)
    except ValueError:
        raise _InvalidPasswordHash(
            PasswordHashStatus.MALFORMED,
            f"invalid {name} in stored hash",
            algorithm=algorithm,
            format_valid=False,
        ) from None


def _parse_password_hash(pwhash: str) -> _ParsedPasswordHash:
    if not isinstance(pwhash, str):
        raise _InvalidPasswordHash(
            PasswordHashStatus.MALFORMED,
            "stored hash must be a string",
            format_valid=False,
        )

    if len(pwhash) > MAX_PASSWORD_HASH_LENGTH:
        raise _InvalidPasswordHash(
            PasswordHashStatus.LIMIT_EXCEEDED,
            "stored hash exceeds the maximum length",
            within_limits=False,
        )

    parts = pwhash.split("$")

    if len(parts) != 3:
        raise _InvalidPasswordHash(
            PasswordHashStatus.MALFORMED,
            "stored hash must contain method, salt, and hash fields",
            format_valid=False,
        )

    method_part, salt, hashval = parts
    method_parts = method_part.split(":")
    algorithm = method_parts[0]

    if not algorithm:
        raise _InvalidPasswordHash(
            PasswordHashStatus.MALFORMED,
            "stored hash is missing an algorithm",
            format_valid=False,
        )

    if algorithm == "scrypt":
        if len(method_parts) == 1:
            n = _DEFAULT_SCRYPT_N
            r = _DEFAULT_SCRYPT_R
            p = _DEFAULT_SCRYPT_P
        elif len(method_parts) == 4:
            n = _parse_decimal(method_parts[1], algorithm=algorithm, name="scrypt n")
            r = _parse_decimal(method_parts[2], algorithm=algorithm, name="scrypt r")
            p = _parse_decimal(method_parts[3], algorithm=algorithm, name="scrypt p")
        else:
            raise _InvalidPasswordHash(
                PasswordHashStatus.MALFORMED,
                "scrypt requires three parameters",
                algorithm=algorithm,
                format_valid=False,
            )

        if n < 2 or n & (n - 1) or r < 1 or p < 1:
            raise _InvalidPasswordHash(
                PasswordHashStatus.MALFORMED,
                "invalid scrypt parameters",
                algorithm=algorithm,
                format_valid=False,
            )

        if (
            n > MAX_SCRYPT_N
            or r > MAX_SCRYPT_R
            or p > MAX_SCRYPT_P
            or 128 * n * r > MAX_SCRYPT_MEMORY
            or n * r * p > MAX_SCRYPT_WORK
        ):
            raise _InvalidPasswordHash(
                PasswordHashStatus.LIMIT_EXCEEDED,
                "scrypt parameters exceed the verification budget",
                algorithm=algorithm,
                within_limits=False,
            )

        return _ParsedPasswordHash(
            algorithm=algorithm,
            method=f"scrypt:{n}:{r}:{p}",
            salt=salt,
            hashval=hashval,
            expected_hash_length=128,
            scrypt_n=n,
            scrypt_r=r,
            scrypt_p=p,
        )

    if algorithm == "pbkdf2":
        if len(method_parts) == 1:
            digest = _DEFAULT_PBKDF2_HASH
            iterations = DEFAULT_PBKDF2_ITERATIONS
        elif len(method_parts) == 2:
            digest = method_parts[1].lower()
            iterations = DEFAULT_PBKDF2_ITERATIONS
        elif len(method_parts) == 3:
            digest = method_parts[1].lower()
            iterations = _parse_decimal(
                method_parts[2], algorithm=algorithm, name="pbkdf2 iteration count"
            )
        else:
            raise _InvalidPasswordHash(
                PasswordHashStatus.MALFORMED,
                "pbkdf2 accepts at most two parameters",
                algorithm=algorithm,
                format_valid=False,
            )

        if not digest:
            raise _InvalidPasswordHash(
                PasswordHashStatus.MALFORMED,
                "pbkdf2 is missing a digest name",
                algorithm=algorithm,
                format_valid=False,
            )

        digest_size = _PBKDF2_DIGEST_SIZES.get(digest)

        if digest_size is None:
            raise _InvalidPasswordHash(
                PasswordHashStatus.UNSUPPORTED_ALGORITHM,
                "stored hash uses an unsupported pbkdf2 digest",
                algorithm=_safe_algorithm_name(digest),
                algorithm_supported=False,
            )

        if iterations < 1:
            raise _InvalidPasswordHash(
                PasswordHashStatus.MALFORMED,
                "pbkdf2 iteration count must be positive",
                algorithm=f"pbkdf2:{digest}",
                format_valid=False,
            )

        if iterations > MAX_PBKDF2_ITERATIONS:
            raise _InvalidPasswordHash(
                PasswordHashStatus.LIMIT_EXCEEDED,
                "pbkdf2 iteration count exceeds the verification budget",
                algorithm=f"pbkdf2:{digest}",
                within_limits=False,
            )

        return _ParsedPasswordHash(
            algorithm=f"pbkdf2:{digest}",
            method=f"pbkdf2:{digest}:{iterations}",
            salt=salt,
            hashval=hashval,
            expected_hash_length=digest_size * 2,
            pbkdf2_digest=digest,
            pbkdf2_iterations=iterations,
        )

    raise _InvalidPasswordHash(
        PasswordHashStatus.UNSUPPORTED_ALGORITHM,
        "stored hash uses an unsupported algorithm",
        algorithm=_safe_algorithm_name(algorithm),
        algorithm_supported=False,
    )


def _validate_salt_and_hash(parsed: _ParsedPasswordHash) -> None:
    if not parsed.salt:
        raise _InvalidPasswordHash(
            PasswordHashStatus.MALFORMED,
            "stored hash is missing a salt",
            algorithm=parsed.algorithm,
            format_valid=False,
        )

    if len(parsed.salt) > MAX_SALT_LENGTH:
        raise _InvalidPasswordHash(
            PasswordHashStatus.LIMIT_EXCEEDED,
            "stored salt exceeds the maximum length",
            algorithm=parsed.algorithm,
            within_limits=False,
        )

    if not parsed.hashval:
        raise _InvalidPasswordHash(
            PasswordHashStatus.MALFORMED,
            "stored hash is missing a hash value",
            algorithm=parsed.algorithm,
            format_valid=False,
        )

    if len(parsed.hashval) > MAX_HASH_LENGTH:
        raise _InvalidPasswordHash(
            PasswordHashStatus.LIMIT_EXCEEDED,
            "stored hash value exceeds the maximum length",
            algorithm=parsed.algorithm,
            within_limits=False,
        )

    if len(parsed.hashval) != parsed.expected_hash_length:
        raise _InvalidPasswordHash(
            PasswordHashStatus.MALFORMED,
            "stored hash value has an invalid length",
            algorithm=parsed.algorithm,
            format_valid=False,
        )

    if not _HEX_RE.fullmatch(parsed.hashval):
        raise _InvalidPasswordHash(
            PasswordHashStatus.MALFORMED,
            "stored hash value is not hexadecimal",
            algorithm=parsed.algorithm,
            format_valid=False,
        )


def _upgrade_assessment(parsed: _ParsedPasswordHash) -> tuple[bool, str | None]:
    reasons: list[str] = []

    if parsed.scrypt_n is not None:
        if parsed.scrypt_n < _DEFAULT_SCRYPT_N:
            reasons.append("scrypt work factor is below the current default")

        if parsed.scrypt_r is not None and parsed.scrypt_r < _DEFAULT_SCRYPT_R:
            reasons.append("scrypt block size is below the current default")
    elif parsed.pbkdf2_digest is not None:
        if parsed.pbkdf2_digest in _WEAK_PBKDF2_DIGESTS:
            reasons.append("pbkdf2 uses a legacy digest")

        if (
            parsed.pbkdf2_iterations is not None
            and parsed.pbkdf2_iterations < DEFAULT_PBKDF2_ITERATIONS
        ):
            reasons.append("pbkdf2 iteration count is below the current default")

    if not reasons:
        return False, None

    return True, "; ".join(reasons)


def _invalid_diagnostic(error: _InvalidPasswordHash) -> PasswordHashDiagnostic:
    return PasswordHashDiagnostic(
        status=error.status,
        valid=False,
        password_matches=False,
        needs_upgrade=True,
        reason=error.reason,
        suggested_method=_RECOMMENDED_METHOD,
        suggested_parameters=_RECOMMENDED_PARAMETERS,
        upgrade_reason=(
            "stored hash cannot be verified; generate a new hash or reset the password"
        ),
        algorithm=error.algorithm,
        format_valid=error.format_valid,
        within_limits=error.within_limits,
        algorithm_supported=error.algorithm_supported,
    )


_os_alt_seps: list[str] = list(
    sep for sep in [os.sep, os.altsep] if sep is not None and sep != "/"
)
# https://chrisdenton.github.io/omnipath/Special%20Dos%20Device%20Names.html
_windows_device_files = {
    "AUX",
    "CON",
    "CONIN$",
    "CONOUT$",
    *(f"COM{c}" for c in "123456789¹²³"),
    *(f"LPT{c}" for c in "123456789¹²³"),
    "NUL",
    "PRN",
}


def _hash_internal(method: str, salt: str, password: str) -> tuple[str, str]:
    method, *args = method.split(":")
    salt_bytes = salt.encode()
    password_bytes = password.encode()

    # Security note: If the method contains args, they came from a stored,
    # trusted hash previously generated by generate_password_hash. An attacker
    # who could modify them can already compromise the entire application.

    if method == "scrypt":
        if not args:
            n = 2**15
            r = 8
            p = 1
        else:
            try:
                n, r, p = map(int, args)
            except ValueError:
                raise ValueError("'scrypt' takes 3 arguments.") from None

        maxmem = 132 * n * r * p  # ideally 128, but some extra seems needed
        return (
            hashlib.scrypt(
                password_bytes, salt=salt_bytes, n=n, r=r, p=p, maxmem=maxmem
            ).hex(),
            f"scrypt:{n}:{r}:{p}",
        )
    elif method == "pbkdf2":
        len_args = len(args)

        if len_args == 0:
            hash_name = "sha256"
            iterations = DEFAULT_PBKDF2_ITERATIONS
        elif len_args == 1:
            hash_name = args[0]
            iterations = DEFAULT_PBKDF2_ITERATIONS
        elif len_args == 2:
            hash_name = args[0]
            iterations = int(args[1])
        else:
            raise ValueError("'pbkdf2' takes 2 arguments.")

        return (
            hashlib.pbkdf2_hmac(
                hash_name, password_bytes, salt_bytes, iterations
            ).hex(),
            f"pbkdf2:{hash_name}:{iterations}",
        )
    else:
        raise ValueError(f"Invalid hash method '{method}'.")


def diagnose_password_hash(pwhash: str, password: str) -> PasswordHashDiagnostic:
    """Check a stored password hash and return a structured, audit-safe result.

    Unlike :func:`check_password_hash`, this reports why a verification failed.
    The stored hash is parsed and bounded before any key derivation function is
    called, so malformed or oversized records cannot consume the KDF budget.

    The returned object never includes the stored salt, stored hash, or the
    supplied password. ``needs_upgrade`` and ``suggested_method`` describe how
    to migrate a valid but outdated record. Use :func:`check_password_hash`
    when only a boolean result is needed.

    :param pwhash: The stored hash to inspect.
    :param password: The plaintext password to compare.

    .. versionadded:: 3.2
    """
    try:
        parsed = _parse_password_hash(pwhash)
        _validate_salt_and_hash(parsed)
    except _InvalidPasswordHash as e:
        return _invalid_diagnostic(e)

    if not isinstance(password, str):
        return PasswordHashDiagnostic(
            status=PasswordHashStatus.MALFORMED,
            valid=False,
            password_matches=False,
            needs_upgrade=False,
            reason="password must be a string",
            algorithm=parsed.algorithm,
            format_valid=False,
        )

    try:
        actual_hash = _hash_internal(parsed.method, parsed.salt, password)[0]
    except MemoryError:
        return _invalid_diagnostic(
            _InvalidPasswordHash(
                PasswordHashStatus.LIMIT_EXCEEDED,
                "stored hash exceeds the verification budget",
                algorithm=parsed.algorithm,
                within_limits=False,
            )
        )
    except (OverflowError, TypeError, ValueError):
        return _invalid_diagnostic(
            _InvalidPasswordHash(
                PasswordHashStatus.MALFORMED,
                "stored hash could not be verified",
                algorithm=parsed.algorithm,
            )
        )

    matches = hmac.compare_digest(actual_hash, parsed.hashval)
    needs_upgrade, upgrade_reason = _upgrade_assessment(parsed)

    return PasswordHashDiagnostic(
        status=(
            PasswordHashStatus.OK if matches else PasswordHashStatus.PASSWORD_MISMATCH
        ),
        valid=matches,
        password_matches=matches,
        needs_upgrade=needs_upgrade,
        reason=(
            "password matches the stored hash"
            if matches
            else "password does not match the stored hash"
        ),
        suggested_method=_RECOMMENDED_METHOD if needs_upgrade else None,
        suggested_parameters=_RECOMMENDED_PARAMETERS if needs_upgrade else None,
        upgrade_reason=upgrade_reason,
        algorithm=parsed.algorithm,
        format_valid=True,
        within_limits=True,
        algorithm_supported=True,
    )


# Descriptive aliases for callers that use a "check with diagnostics" naming
# convention.
check_password_hash_with_diagnostics = diagnose_password_hash
check_password_hash_diagnostics = diagnose_password_hash
check_password_hash_diagnostic = diagnose_password_hash

PasswordHashCheckResult = PasswordHashDiagnostic


def generate_password_hash(
    password: str, method: str = "scrypt", salt_length: int = 16
) -> str:
    """Securely hash a password for storage. A password can be compared to a stored hash
    using :func:`check_password_hash`.

    The following methods are supported:

    -   ``scrypt``, the default. The parameters are ``n``, ``r``, and ``p``, the default
        is ``scrypt:32768:8:1``. See :func:`hashlib.scrypt`.
    -   ``pbkdf2``, less secure. The parameters are ``hash_method`` and ``iterations``,
        the default is ``pbkdf2:sha256:600000``. See :func:`hashlib.pbkdf2_hmac`.

    Default parameters may be updated to reflect current guidelines, and methods may be
    deprecated and removed if they are no longer considered secure. To migrate old
    hashes, you may generate a new hash when checking an old hash, or you may contact
    users with a link to reset their password.

    :param password: The plaintext password.
    :param method: The key derivation function and parameters.
    :param salt_length: The number of characters to generate for the salt.

    .. versionchanged:: 3.1
        The default iterations for pbkdf2 was increased to 1,000,000.

    .. versionchanged:: 3.0
        All plain hashes are no longer supported.

    .. versionchanged:: 2.3
        Scrypt support was added.

    .. versionchanged:: 2.3
        The default iterations for pbkdf2 was increased to 600,000.
    """
    if salt_length <= 0:
        raise ValueError("Salt length must be at least 1.")

    salt = secrets.token_urlsafe(salt_length)
    h, actual_method = _hash_internal(method, salt, password)
    return f"{actual_method}${salt}${h}"


def check_password_hash(pwhash: str, password: str) -> bool:
    """Securely check that the given stored password hash, previously generated using
    :func:`generate_password_hash`, matches the given password.

    Methods may be deprecated and removed if they are no longer considered secure. To
    migrate old hashes, you may generate a new hash when checking an old hash, or you
    may contact users with a link to reset their password.

    :param pwhash: The hashed password.
    :param password: The plaintext password.

    Returns ``False`` for malformed, unsupported, or over-budget stored hashes
    instead of raising an exception. Use :func:`diagnose_password_hash` when
    the reason for failure needs to be audited.

    .. versionchanged:: 3.2
        Invalid stored hashes return ``False`` rather than raising.

    .. versionchanged:: 3.0
        All plain hashes are no longer supported.
    """
    return diagnose_password_hash(pwhash, password).valid


def safe_join(directory: str, *untrusted: str) -> str | None:
    """Safely join zero or more untrusted path components to a trusted base
    directory to avoid escaping the base directory. Return ``None`` if the path
    is not safe.

    The untrusted path is assumed to be from/for a URL, such as for serving
    files. Therefore, it should only use the forward slash ``/`` path separator,
    and will be joined using that separator. On Windows, the backslash ``\\``
    separator is not allowed.

    This only considers the path name, it does not validate if it does or does
    not exist, if it is a symlink, or other properties of the file or
    filesystem. It's up to the application to ensure that the contents of
    ``directory`` can be trusted.

    On Windows, special device names such as ``CON`` and ``NUL`` are not
    allowed, as this is used for serving files with :func:`.send_from_directory`
    and those files will hang when read.

    NTFS alternate data streams (ADS) like ``filename:stream`` are
    allowed. :func:`.secure_filename` will remove the ``:`` when saving.

    :param directory: The trusted base directory.
    :param untrusted: The untrusted path components relative to the
        base directory.
    :return: A safe path, otherwise ``None``.

    .. versionchanged:: 3.1.9
        Special device names with empty ADS stream markers are not allowed on
        Windows.

    .. versionchanged:: 3.1.6
        Special device names in multi-segment paths are not allowed on Windows.

    .. versionchanged:: 3.1.5
        More special device names, regardless of extension or trailing spaces,
        are not allowed on Windows.

    .. versionchanged:: 3.1.4
        Special device names are not allowed on Windows.
    """
    if not directory:
        # Ensure we end up with ./path if directory="" is given,
        # otherwise the first untrusted part could become trusted.
        directory = "."

    parts = [directory]

    for part in untrusted:
        if not part:
            continue

        part = posixpath.normpath(part)

        if (
            os.path.isabs(part)
            # ntpath.isabs doesn't catch this
            or part.startswith("/")
            or part == ".."
            or part.startswith("../")
            or any(sep in part for sep in _os_alt_seps)
            or (
                os.name == "nt"
                and any(
                    p.partition(":")[0].partition(".")[0].strip().upper()
                    in _windows_device_files
                    for p in part.split("/")
                )
            )
        ):
            return None

        parts.append(part)

    return posixpath.join(*parts)
